      { id: "purpose", title: "Purpose of regulation", titleFr: "Rôle de la réglementation", facts: ["Financial regulation aims to protect market integrity, investors and system stability.", "Rules differ by jurisdiction, product and role, so professionals must know their applicable framework."], factsFr: ["La réglementation vise intégrité des marchés, protection investisseurs et stabilité du système.", "Les règles varient selon juridiction, produit et rôle ; les professionnels doivent connaître leur cadre applicable." ] },
      { id: "conflicts", title: "Conflicts of interest", titleFr: "Conflits d’intérêts", facts: ["Conflicts should be identified, managed and disclosed where required.", "Compensation structures can influence advice even when the product itself is legal."], factsFr: ["Les conflits doivent être identifiés, gérés et divulgués lorsque nécessaire.", "Les structures de rémunération peuvent influencer le conseil même si le produit est légal." ] },
      { id: "mnpi", title: "MNPI & insider trading", titleFr: "MNPI & insider trading", facts: ["Material nonpublic information can create trading and communication restrictions.", "Information barriers help separate teams with conflicting information access."], factsFr: ["Une information matérielle non publique peut créer des restrictions de trading et communication.", "Les information barriers séparent les équipes ayant des accès différents." ] },
      { id: "market-abuse", title: "Market abuse", titleFr: "Market abuse", facts: ["Manipulation, spoofing and misleading communications undermine market integrity.", "Intent, conduct and market impact can all matter in enforcement."], factsFr: ["Manipulation, spoofing et communications trompeuses nuisent à l’intégrité du marché.", "Intention, conduite et impact peuvent tous compter dans l’enforcement." ] },
      { id: "suitability", title: "Suitability & fiduciary duty", titleFr: "Suitability & fiduciary duty", facts: ["A suitable recommendation must reflect client objectives, constraints and risk profile.", "A fiduciary standard generally requires acting in the client’s best interest where applicable."], factsFr: ["Une recommandation adaptée doit refléter objectifs, contraintes et profil de risque.", "Un standard fiduciary exige généralement d’agir dans le meilleur intérêt du client lorsqu’il s’applique." ] },
      { id: "disclosure", title: "Disclosure & communication", titleFr: "Disclosure & communication", facts: ["Research and client communications should distinguish fact, opinion, estimate and conflict disclosures.", "Selective or misleading presentation can create legal and ethical problems."], factsFr: ["Les communications doivent distinguer faits, opinions, estimations et disclosures de conflits.", "Une présentation sélective ou trompeuse peut créer des problèmes juridiques et éthiques." ] },
      { id: "escalation", title: "Escalation & documentation", titleFr: "Escalation & documentation", facts: ["When uncertain, professionals should escalate to compliance or legal rather than improvise around restrictions.", "Clear documentation supports accountability and consistent decisions."], factsFr: ["En cas d’incertitude, il faut escalader vers compliance ou legal plutôt qu’improviser autour des restrictions.", "Une documentation claire soutient accountability et cohérence." ] },
      { id: "ethics", title: "Ethical decision framework", titleFr: "Framework de décision éthique", facts: ["Ethical conduct can require a higher standard than minimum legal compliance.", "A useful test asks who is affected, which duties conflict and whether the decision could be defended transparently."], factsFr: ["L’éthique peut exiger un standard supérieur au minimum légal.", "Un bon test demande qui est affecté, quels devoirs entrent en conflit et si la décision peut être défendue de façon transparente." ] }
